/**
 * Lookup for the bioscience gloss layer. See `terms.ts` for what a gloss is
 * allowed to do (annotate, never replace; never indexed for search).
 *
 * Two tiers:
 *
 * - **curated** — bundled, synchronous, reviewed for the terms this product
 *   shows. Always wins.
 * - **dictionary** — `static/glossary/zh.json`, generated by
 *   `tools/glossary/build.mjs` from Wikidata (CC0, exact-label gated). Lazy:
 *   it is not in the JS bundle and is fetched the first time a gloss is asked
 *   for, so a reader who never needs it pays nothing. A failed fetch leaves
 *   the curated tier working.
 *
 * Organism strings need the most work: a catalog row reads
 * `Oryza sativa subsp. japonica` or `Vibrio vulnificus (strain CMCP6)`, and
 * the species is the glossable part. Strain suffixes are dropped rather than
 * glossed — nobody needs 中文 for "ATCC 204508 / S288c".
 */
import { GLOSSARY, type TermGloss } from './terms';

const BY_LOWER = new Map<string, TermGloss>();
for (const [term, gloss] of Object.entries(GLOSSARY)) {
	BY_LOWER.set(term.toLowerCase(), gloss);
}

/** term (lowercase) → zh, filled by `loadDictionary()`. */
let dictionary: Map<string, string> | null = null;
let inflight: Promise<void> | null = null;

/** A catalog organism string with its strain/subspecies qualifiers removed. */
export function speciesOf(name: string): string {
	const trimmed = name.replace(/\s+/g, ' ').trim();
	const beforeStrain = trimmed.split(' (')[0];
	const beforeSubspecies = beforeStrain.split(/\s+subsp\.?\s+/i)[0];
	return beforeSubspecies.trim();
}

/** Genus + species of a qualified name ("Human adenovirus B serotype 3"). */
function firstTwoWords(name: string): string {
	return name.trim().split(' ').slice(0, 2).join(' ');
}

/**
 * Fetch the generated dictionary once. Safe to call before every lookup:
 * after the first success it is a no-op. A failure is recorded as an empty
 * dictionary so a flaky network cannot retry on every hover.
 */
export function loadDictionary(url = '/glossary/zh.json'): Promise<void> {
	if (dictionary) return Promise.resolve();
	if (inflight) return inflight;
	inflight = (async () => {
		const map = new Map<string, string>();
		try {
			const res = await fetch(url);
			if (res.ok) {
				const body = (await res.json()) as { terms?: Record<string, { zh?: string }> };
				for (const [term, entry] of Object.entries(body.terms ?? {})) {
					if (entry?.zh) map.set(term.toLowerCase(), entry.zh);
				}
			}
		} catch {
			// Offline or a stale deployment: the curated tier still answers.
		}
		dictionary = map;
		inflight = null;
	})();
	return inflight;
}

export function dictionaryLoaded(): boolean {
	return dictionary !== null;
}

function dictionaryHit(term: string): string | undefined {
	if (!dictionary) return undefined;
	const direct = dictionary.get(term.toLowerCase());
	if (direct) return direct;
	for (const candidate of [speciesOf(term), firstTwoWords(speciesOf(term))]) {
		const hit = dictionary.get(candidate.toLowerCase());
		if (hit) return hit;
	}
	return undefined;
}

export function gloss(term: string | null | undefined): TermGloss | undefined {
	if (!term) return undefined;
	const trimmed = term.replace(/\s+/g, ' ').trim();
	if (!trimmed) return undefined;
	const exact = BY_LOWER.get(trimmed.toLowerCase());
	if (exact) return exact;
	// Only an organism may be reached through a shortened form: a keyword with
	// a parenthetical must not resolve to a different reading.
	for (const candidate of [speciesOf(trimmed), firstTwoWords(speciesOf(trimmed))]) {
		const hit = BY_LOWER.get(candidate.toLowerCase());
		if (hit?.category === 'organism') return hit;
	}
	const zh = dictionaryHit(trimmed);
	return zh ? { zh, category: 'keyword' } : undefined;
}

/** The Chinese reading, or undefined when the term is not glossed. */
export function glossZh(term: string | null | undefined): string | undefined {
	return gloss(term)?.zh;
}

export function hasGloss(term: string | null | undefined): boolean {
	return gloss(term) !== undefined;
}
